from devkit.ini import parse, ParseError, InterpolationError
def err(text, cls):
    try:
        parse(text)
    except cls as e:
        return str(e)
    raise AssertionError(text)
text = """
# comment
 ; indented comment
  [ main ]
Name = Alice
path: /home/${name}/x
url = a=b:c
k:v=w
desc = first
   second
\tthird

   [other]
x = ${main:NAME} $$ ${notref $5 $
y = $${x}
[main]
name = Bob
multi = a
# stop
z = ${ Path }
"""
r = parse(text); print(r)
assert list(r) == ["main", "other"]
assert list(r["main"]) == ["name","path","url","k","desc","multi","z"]
assert r["main"]["path"] == "/home/Bob/x" and r["main"]["url"] == "a=b:c" and r["main"]["k"] == "v=w"
assert r["main"]["desc"] == "first\nsecond\nthird" and r["main"]["z"] == "/home/Bob/x"
assert r["other"] == {"x": "Bob $ ${notref $5 $", "y": "${x}"}
assert parse("[s]\na = $${b}\nb = 1\nc = ${a}")["s"]["c"] == "${b}"
assert parse("[s]\na=${b}\nb=${c}\nc=3")["s"]["a"] == "3"
assert parse("[s]\nx=1\n  [t]\ny=2") == {"s": {"x": "1\n[t]", "y": "2"}}
assert parse("[s]\n  y = 2") == {"s": {"y": "2"}}
assert parse("[s]\nx=1\n\n  y = 2") == {"s": {"x": "1", "y": "2"}}
assert parse("[A]\nx=1\n[a]\nx=2") == {"A": {"x": "1"}, "a": {"x": "2"}}
assert parse("[a:b]\nk=1\n[c]\nr=${a:b:k}")["c"]["r"] == "1"
assert parse("[s]\na=1\nb=2\na=3") == {"s": {"a": "3", "b": "2"}}
assert parse("") == {} and parse("[e]") == {"e": {}}
assert parse("[s]\r\nk = v\r\n") == {"s": {"k": "v"}}
for t in ["x=1\n[s]", "[s]\n\njunk", "[s]\n = 1", "[s]\n:1", "[s\nk=1"]:
    print(repr(t), "->", err(t, ParseError))
for t in ["[s]\na=${b}", "[s]\na=${t:b}", "[s]\na=${b}\nb=${a}", "[s]\na=${a}", "[s]\na=${}", "[s]\n[t]\na=${s:b}"]:
    print(repr(t), "->", err(t, InterpolationError))
print("ok")
'

